(async()=>{if(new URLSearchParams(location.search).get('profile')!=='landscape-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,output=document.createElement('section');output.id='landscapeCheck';output.style='position:fixed;inset:0;z-index:10000;background:#142124;color:white;overflow:auto;padding:20px;font:14px monospace';document.body.append(output);const report=document.createElement('pre');report.id='report';output.append(report);document.getElementById('welcome').hidden=true;q.close();q.setPlaying(false);const fresh=q.snapshot(),result={enemies:q.entities.length,rockTypes:NaturalRocks.types.map(t=>t.name),walk:[],pictures:[]};
 async function shot(state,label){q.apply({...structuredClone(fresh),...state});await wait(1500);q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id=label;im.alt=label;im.style='width:49%;display:inline-block';im.src=q.renderer.domElement.toDataURL('image/png');output.append(im);result.pictures.push(label);}
 for(const c of W.caves){const p=W.cavePoint(c,0,-5);q.apply({...structuredClone(fresh),...p,y:W.floor(p.x,p.z,W.ground(p.x,p.z)),yaw:Math.atan2(-c.fx,-c.fz),pitch:0});q.keys({KeyW:true});for(let n=0;n<210;n++)q.move(1/60);q.keys({});const inside=W.caveLocal(c,q.state.x,q.state.z).s;q.keys({KeyS:true});for(let n=0;n<210;n++)q.move(1/60);q.keys({});result.walk.push({id:c.id,inside,exit:W.caveLocal(c,q.state.x,q.state.z).s});}
 const c=W.caves[0],p=W.cavePoint(c,0,-8);await shot({...p,y:W.ground(p.x,p.z),yaw:Math.atan2(-c.fx,-c.fz),pitch:.38},'entrance');const mouth=W.cavePoint(c,0,-2);await shot({...mouth,y:W.caveFloor(c,0,-2),yaw:Math.atan2(-c.fx,-c.fz),pitch:0},'mouth');const d=W.sites.desert;await shot({x:d.x,z:d.z,y:W.ground(d.x,d.z),yaw:1.4,pitch:-.55},'desert');result.sandTexture=q.world.native.desertSand.image?.src;
 await shot({x:0,z:24,y:W.ground(0,24),yaw:0,pitch:-.15},'landscape');result.rockInstances=[...q.world.native.chunks.values()].filter(c=>!c.userData.distant).flatMap(c=>c.userData.rocks||[]).length;
 // Render all ten actual shared meshes, with the same texture used by the game.
 const scene=new THREE.Scene();scene.background=new THREE.Color('#c5c9c4');scene.add(new THREE.HemisphereLight('#ffffff','#6a6355',1.4));const sun=new THREE.DirectionalLight('#fff2d7',2);sun.position.set(-10,25,18);scene.add(sun);const material=NaturalRocks.material(q.world.native.originals.rock);for(let i=0;i<10;i++){const t=NaturalRocks.types[i],m=new THREE.Mesh(NaturalRocks.geometries[i],material);m.scale.set(t.sx,t.sy,t.sz);m.position.set((i%5-2)*6,0,Math.floor(i/5)*7);m.rotation.y=.3;scene.add(m);}const cam=new THREE.PerspectiveCamera(40,1600/900,.1,100);cam.position.set(6,20,29);cam.lookAt(0,0,3);const size=q.renderer.getSize(new THREE.Vector2());q.renderer.setSize(1600,900,false);q.renderer.render(scene,cam);const im=document.createElement('img');im.id='rocks';im.alt='rocks';im.src=q.renderer.domElement.toDataURL();im.style='width:100%';output.append(im);q.renderer.setSize(size.x,size.y,false);
 const legacy=structuredClone(fresh);legacy.finalAwake=true;legacy.enemyStates={final:{hp:850,deadUntil:0}};for(const enemy of SurvivalData.enemies)legacy.enemyStates[enemy.id+'-0']={hp:100,deadUntil:0};q.apply(legacy);q.spawnFinal();result.enemiesAfterRestore=q.entities.length;
 const shopState=structuredClone(fresh);Object.assign(shopState,{x:14,z:9,y:W.ground(14,9),money:1000});q.apply(shopState);q.shop();document.querySelector('[data-action="shop:buy"]').click();q.trade('buy','hide');q.trade('buy','wing');result.shopMaterials={hide:q.state.inventory.hide,wing:q.state.inventory.wing};q.close();report.textContent=JSON.stringify(result,null,2);document.title='地形確認完了';})().catch(e=>{document.body.insertAdjacentHTML('beforeend','<pre id="report">'+e.stack+'</pre>');});
